44: /** 18th birthday must have occurred on or before today's local calendar date. */
45: export function isLegalAge(birthDateIso: string, today: Date = new Date()): boolean {
46:   const birthDate = parseIsoDate(birthDateIso);
47:   if (!birthDate) {
48:     return false;
49:   }
50: 
51:   const localToday = new Date(today.getFullYear(), today.getMonth(), today.getDate());
52:   if (birthDate > localToday) {
53:     return false;
54:   }
55: 
56:   const turning18Year = birthDate.getFullYear() + 18;
57:   const anniversaryMonth = birthDate.getMonth();
58:   let anniversaryDay = birthDate.getDate();
59:   if (anniversaryMonth === 1 && anniversaryDay === 29 && !isLeapYear(turning18Year)) {
60:     anniversaryDay = 28;
61:   }
62: 
63:   const turns18 = new Date(turning18Year, anniversaryMonth, anniversaryDay);
64:   return turns18 <= localToday;
65: }
