74: /** Strict módulo-11 check digit; accepts dotted, dashed or bare RUTs. */
75: export function isValidClRut(value: string): boolean {
76:   const cleaned = value.replace(/[.\s-]/g, '').toUpperCase();
77:   const match = /^(\d{7,8})([0-9K])$/.exec(cleaned);
78:   if (!match) {
79:     return false;
80:   }
81: 
82:   const body = match[1];
83:   const checkDigit = match[2];
84:   let sum = 0;
85:   let multiplier = 2;
86:   for (let index = body.length - 1; index >= 0; index -= 1) {
87:     sum += Number(body.charAt(index)) * multiplier;
88:     multiplier = multiplier === 7 ? 2 : multiplier + 1;
89:   }
90: 
91:   const remainder = 11 - (sum % 11);
92:   const expected = remainder === 11 ? '0' : remainder === 10 ? 'K' : String(remainder);
93:   return checkDigit === expected;
