50:   private readonly quoteClockSignal = signal<QuoteClock | null>(null);
51: 
52:   private changes: Subscription | null = null;
53:   private activeLoad: { readonly country: CountryCode; readonly promise: Promise<void> } | null = null;
54: 
55:   readonly fields = this.fieldsSignal.asReadonly();
56:   readonly countryConfig = this.configSignal.asReadonly();
57:   readonly status = this.statusSignal.asReadonly();
58:   readonly errorMessage = this.errorMessageSignal.asReadonly();
59:   readonly form = this.formSignal.asReadonly();
60:   readonly submitted = this.submittedSignal.asReadonly();
61:   readonly restoredFromDraft = this.restoredSignal.asReadonly();
62:   readonly selectedPlanDocumentId = this.selectedPlanSignal.asReadonly();
63:   readonly plans = this.plansSignal.asReadonly();
64:   readonly plansStatus = this.plansStatusSignal.asReadonly();
65:   readonly plansError = this.plansErrorSignal.asReadonly();
66:   readonly invalidSelectionNotice = this.invalidSelectionNoticeSignal.asReadonly();
67:   readonly restoredSelectionNotice = this.restoredSelectionNoticeSignal.asReadonly();
68: 
69:   /** Recomputed on every form value/status change so Step 2 pricing never goes stale. */
70:   readonly step1Values = computed<Readonly<Record<string, FormValue>>>(() => {
71:     this.formRevision();
72:     const form = this.formSignal();
73:     if (!form) {
74:       return {};
75:     }
76: 
77:     const values: Record<string, FormValue> = {};
78:     for (const field of this.fieldsSignal()) {
79:       const control = form.controls[field.key];
80:       values[field.key] = control
81:         ? coerceDraftValue(field, control.value)
82:         : this.factory.defaultValue(field);
83:     }
84:     return values;
85:   });
86: 
87:   readonly quotedPlans = computed<readonly QuotedPlan[]>(() => {
88:     const pricingStep1 = pickKeys(this.step1Values(), this.fieldsSignal());
89:     const locale = this.context.locale();
90:     const currency = this.context.currency();
91:     const clock = this.quoteClockSignal() ?? this.injectedClock;
92: 
93:     return this.plansSignal().map((plan) => {
94:       const adjustment = calculateAdjustedPrice(plan.basePrice, pricingStep1, clock);
95:       return {
96:         plan,
97:         basePrice: plan.basePrice,
98:         finalPrice: adjustment.finalPrice,
99:         formattedBasePrice: formatCurrency(plan.basePrice, locale, currency),
100:         formattedFinalPrice: formatCurrency(adjustment.finalPrice, locale, currency),
101:         adjustment,
102:       };
103:     });
104:   });
105: 
106:   readonly selectedPlan = computed<InsurancePlan | null>(() => {
107:     const documentId = this.selectedPlanDocumentId();
108:     if (documentId === null) {
109:       return null;
110:     }
111:     return this.plansSignal().find((plan) => plan.documentId === documentId) ?? null;
112:   });
113: 
114:   readonly canAdvance = computed<boolean>(
115:     () => this.plansStatusSignal() === 'ready' && this.selectedPlan() !== null,
116:   );
117: 
118:   readonly isReady = computed<boolean>(() => this.statusSignal() === 'ready' && this.formSignal() !== null);
119: 
120:   readonly errorCount = computed<number>(() => {
121:     this.formRevision();
122:     const form = this.formSignal();
123:     if (!this.submittedSignal() || !form) {
124:       return 0;
125:     }
126:     return Object.values(form.controls).reduce((count, control) => count + (control.invalid ? 1 : 0), 0);
127:   });
128: 
129:   constructor() {
130:     this.destroyRef.onDestroy(() => this.changes?.unsubscribe());
131:   }
132: 
133:   /** Reuses an in-flight/resolved load for the same country to avoid duplicate requests. */
134:   load(country: CountryCode): Promise<void> {
135:     if (this.activeLoad?.country === country && this.statusSignal() !== 'error') {
136:       return this.activeLoad.promise;
137:     }
138:     const promise = this.startLoad(country);
139:     this.activeLoad = { country, promise };
140:     return promise;
141:   }
142: 
143:   retry(): Promise<void> {
144:     this.activeLoad = null;
145:     return this.load(this.activeCountrySignal() ?? this.context.country());
146:   }
147: 
148:   /** The Step 2 page hands over the clock instance captured on entry. */
149:   captureClock(clock: QuoteClock): void {
150:     this.quoteClockSignal.set(clock);
151:   }
152: 
153:   async loadPlans(country: CountryCode): Promise<void> {
154:     this.plansStatusSignal.set('loading');
155:     this.plansErrorSignal.set(null);
156: 
157:     try {
158:       const plans = await firstValueFrom(this.catalogue.getInsurancePlans(country));
159:       this.plansSignal.set(plans);
160:       this.normalizeSelection(plans, country);
161:       this.plansStatusSignal.set(plans.length > 0 ? 'ready' : 'empty');
162:     } catch (error: unknown) {
163:       // Keep the previous catalogue, selection and persisted draft untouched (US-02 G20).
164:       this.plansErrorSignal.set(this.describeError(error));
165:       this.plansStatusSignal.set('error');
166:     }
167:   }
168: 
169:   retryPlans(): Promise<void> {
170:     return this.loadPlans(this.activeCountrySignal() ?? this.context.country());
171:   }
172: 
173:   selectPlan(documentId: string | null): void {
174:     if (documentId !== null && !this.plansSignal().some((plan) => plan.documentId === documentId)) {
175:       return;
176:     }
177: 
178:     this.selectedPlanSignal.set(documentId);
179:     this.invalidSelectionNoticeSignal.set(false);
180:     this.restoredSelectionNoticeSignal.set(false);
181:     this.persist('plans');
182:   }
183: 
184:   persist(step: WizardStep): void {
185:     const form = this.formSignal();
186:     const country = this.activeCountrySignal() ?? this.context.country();
187:     if (!form || this.statusSignal() !== 'ready') {
188:       return;
189:     }
190: 
191:     const step1: Record<string, FormValue> = {};
192:     for (const field of this.fieldsSignal()) {
193:       const control = form.controls[field.key];
194:       step1[field.key] = control
195:         ? coerceDraftValue(field, control.value)
196:         : this.factory.defaultValue(field);
197:     }
198: 
199:     const state: PersistedWizardStateV1 = {
200:       schemaVersion: 1,
201:       country,
202:       savedAt: new Date().toISOString(),
203:       step,
204:       step1,
205:       selectedPlanDocumentId: this.selectedPlanSignal(),
206:     };
207:     this.persistence.save(state);
208:   }
209: 
210:   patchValues(values: Readonly<Record<string, FormValue>>): void {
211:     const form = this.formSignal();
212:     if (!form) {
213:       return;
214:     }
215:     for (const field of this.fieldsSignal()) {
216:       const control = form.controls[field.key];
217:       const value = values[field.key];
218:       if (control && value !== undefined) {
219:         control.setValue(coerceDraftValue(field, value));
220:       }
221:     }
222:   }
223: 
224:   markSubmitted(): void {
225:     this.submittedSignal.set(true);
226:   }
227: 
228:   isLoadedFor(country: CountryCode): boolean {
229:     return (
230:       this.activeCountrySignal() === country &&
231:       this.statusSignal() === 'ready' &&
232:       this.formSignal() !== null
233:     );
234:   }
235: 
236:   reset(country: CountryCode): void {
237:     this.changes?.unsubscribe();
238:     this.changes = null;
239:     this.activeLoad = null;
240:     this.persistence.clear(country);
241:     this.activeCountrySignal.set(null);
242:     this.fieldsSignal.set([]);
243:     this.configSignal.set(null);
244:     this.formSignal.set(null);
245:     this.statusSignal.set('idle');
246:     this.errorMessageSignal.set(null);
247:     this.submittedSignal.set(false);
248:     this.restoredSignal.set(false);
249:     this.selectedPlanSignal.set(null);
250:     this.formRevision.set(0);
251:     this.clearPlanState();
252:   }
253: 
254:   private async startLoad(country: CountryCode): Promise<void> {
255:     this.changes?.unsubscribe();
256:     this.changes = null;
257:     this.activeCountrySignal.set(country);
258:     this.statusSignal.set('loading');
259:     this.errorMessageSignal.set(null);
260:     this.submittedSignal.set(false);
261:     this.restoredSignal.set(false);
262:     this.clearPlanState();
263: 
264:     try {
265:       const { fields, config } = await firstValueFrom(
266:         forkJoin({
267:           fields: this.catalogue.getFormFields(country),
268:           config: this.catalogue.getCountryConfig(country),
269:         }),
270:       );
271: 
272:       this.fieldsSignal.set(fields);
273:       this.configSignal.set(config);
274: 
275:       if (fields.length === 0) {
276:         this.formSignal.set(null);
277:         this.selectedPlanSignal.set(null);
278:         this.restoredSelectionFromDraftSignal.set(false);
279:         this.statusSignal.set('empty');
280:         return;
281:       }
282: 
283:       const draft = this.persistence.load(country);
284:       const values: Record<string, FormValue> = {};
285:       for (const field of fields) {
286:         const raw = draft?.step1[field.key];
287:         values[field.key] = raw === undefined ? this.factory.defaultValue(field) : coerceDraftValue(field, raw);
288:       }
289: 
290:       const form = this.factory.createForm(fields, values);
291:       this.formSignal.set(form);
292:       this.restoredSelectionFromDraftSignal.set(draft?.selectedPlanDocumentId != null);
293:       this.selectedPlanSignal.set(draft?.selectedPlanDocumentId ?? null);
294: 
295:       const hasRestoredValues = Boolean(draft && Object.keys(draft.step1).length > 0);
296:       if (hasRestoredValues) {
297:         form.markAllAsTouched();
298:         this.restoredSignal.set(true);
299:       }
300:       form.updateValueAndValidity({ emitEvent: false });
301:       this.statusSignal.set('ready');
302: 
303:       this.changes = new Subscription();
304:       this.changes.add(
305:         form.statusChanges.subscribe(() => this.formRevision.update((revision) => revision + 1)),
306:       );
307:       this.changes.add(
308:         form.valueChanges.pipe(debounceTime(400)).subscribe(() => this.persist('policyholder')),
309:       );
310:     } catch (error: unknown) {
311:       this.errorMessageSignal.set(this.describeError(error));
312:       this.statusSignal.set('error');
313:     }
314:   }
315: 
316:   private normalizeSelection(plans: readonly InsurancePlan[], country: CountryCode): void {
317:     const selected = this.selectedPlanSignal();
318:     const restoredFromDraft = this.restoredSelectionFromDraftSignal();
319: 
320:     if (selected !== null && plans.some((plan) => plan.documentId === selected)) {
321:       this.invalidSelectionNoticeSignal.set(false);
322:       this.restoredSelectionNoticeSignal.set(restoredFromDraft);
323:       return;
324:     }
325: 
326:     if (selected !== null) {
327:       this.selectedPlanSignal.set(null);
328:       this.clearPersistedSelection(country);
329:       this.invalidSelectionNoticeSignal.set(true);
330:     } else {
331:       this.invalidSelectionNoticeSignal.set(false);
332:     }
333:     this.restoredSelectionNoticeSignal.set(false);
334:   }
335: 
336:   /** Clears only the plan id; `step1` and `savedAt` stay byte-identical (US-02 G12). */
337:   private clearPersistedSelection(country: CountryCode): void {
338:     const draft = this.persistence.load(country);
339:     if (!draft || draft.selectedPlanDocumentId === null) {
340:       return;
341:     }
342:     const cleared: PersistedWizardStateV1 = { ...draft, selectedPlanDocumentId: null };
343:     this.persistence.save(cleared);
344:   }
345: 
346:   private clearPlanState(): void {
347:     this.plansSignal.set([]);
348:     this.plansStatusSignal.set('idle');
349:     this.plansErrorSignal.set(null);
350:     this.invalidSelectionNoticeSignal.set(false);
351:     this.restoredSelectionNoticeSignal.set(false);
352:     this.restoredSelectionFromDraftSignal.set(false);
353:     this.quoteClockSignal.set(null);
354:   }
355: 
356:   private describeError(error: unknown): string | null {
357:     if (!isDevMode()) {
358:       return null;
359:     }
360:     if (error instanceof HttpErrorResponse) {
361:       return `HTTP ${error.status} ${error.statusText}`.trim();
362:     }
363:     return error instanceof Error ? error.message : null;
364:   }
365: }

